import {describe,expect,it} from 'vitest';
import {readFileSync,mkdtempSync} from 'node:fs';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {compile} from '../src/compiler.js';
import {generate} from '../src/generator/generate.js';
import {parse} from '../src/parser/parser.js';
import {validateSerializedIR} from '../src/ir/validate.js';
import {bundleBrowserArtifact} from '../src/release/browser-bundle.js';

describe('controlled-English UI binding diagnostics',()=>{
 it('binds typed action parameters from repeated list items in canonical UI IR and browser output',()=>{const source='app Shop\nmodel Product { sku text required }\nmodel CartLine { sku text required }\napi /cart-lines from CartLine\ncomponent ProductRow { show product sku button "Add" on add with sku from product.sku }\npage Store { event add(sku text) sends POST "/cart-lines" state products list<Product> for each product in products show ProductRow }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components.find(component=>component.name==='ProductRow')!.children).toContainEqual({kind:'button',label:'Add',event:'add',arguments:[{name:'sku',path:'product.sku'}]});expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-row-action-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('&quot;arguments&quot;:{&quot;sku&quot;:{&quot;path&quot;:&quot;product.sku&quot;}}');expect(html).toContain('clone.dataset.pipeRow=JSON.stringify(value)');bundleBrowserArtifact(directory);const bundle=readFileSync(join(directory,'app.js'),'utf8');expect(bundle).toContain('pipeRowItem');expect(bundle).toContain('row bindings');});
 it('rejects row action bindings with missing, unknown, or mismatched typed fields',()=>{const missing=compile('app Shop\nmodel Product { sku text }\nmodel CartLine { sku text }\napi /cart-lines from CartLine\ncomponent ProductRow { button "Add" on add with missing from product.sku }\npage Store { event add(sku text) sends POST "/cart-lines" state products list<Product> for each product in products show ProductRow }');expect(missing.diagnostics.map(diagnostic=>diagnostic.code)).toContain('PIPE-UI-019');const mismatch=compile('app Shop\nmodel Product { quantity integer }\nmodel CartLine { quantity text }\napi /cart-lines from CartLine\ncomponent ProductRow { button "Add" on add with quantity from product.quantity }\npage Store { event add(quantity text) sends POST "/cart-lines" state products list<Product> for each product in products show ProductRow }');expect(mismatch.diagnostics.map(diagnostic=>diagnostic.code)).toContain('PIPE-UI-019');});
 it('binds a page-state value alongside typed form inputs for one action',()=>{const source='app Shop\nmodel CartLine { name text required quantity integer required }\nmodel CheckoutRequest { customerName text required customerEmail text required deliveryAddress text required items list<CartLine> required }\napi /checkout from CheckoutRequest\ncomponent CheckoutForm form { input customerName text input customerEmail text input deliveryAddress text button "Complete checkout" on checkout with items from cart }\npage Store { event checkout(customerName text, customerEmail text, deliveryAddress text, items list<CartLine>) sends POST "/checkout" use CheckoutForm state cart list<CartLine> = [] persisted in local storage }';const result=compile(source);expect(result.diagnostics).toEqual([]);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-state-action-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('&quot;items&quot;:{&quot;path&quot;:&quot;cart&quot;,&quot;source&quot;:&quot;state&quot;}');expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('rejects a page-state action binding with a mismatched TypeRef',()=>{const source='app Shop\nmodel CartLine { quantity integer required }\nmodel CheckoutRequest { items text required }\napi /checkout from CheckoutRequest\ncomponent CheckoutForm form { button "Complete" on checkout with items from cart }\npage Store { event checkout(items text) sends POST "/checkout" use CheckoutForm state cart list<CartLine> = [] }';expect(compile(source).diagnostics.map(diagnostic=>diagnostic.code)).toContain('PIPE-UI-019');});
 it('allows a generated integer model id as a repeated-row action argument',()=>{const source='app Shop\nmodel Product { sku text required }\nmodel CartLine { productId integer required }\napi /cart-lines from CartLine\ncomponent ProductRow { button "Add" on add with productId from product.id }\npage Store { event add(productId integer) sends POST "/cart-lines" state products list<Product> for each product in products show ProductRow }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components.find(component=>component.name==='ProductRow')!.children).toContainEqual(expect.objectContaining({kind:'button',arguments:[{name:'productId',path:'product.id'}]}));});
 it('compiles typed repeated-row list updates and browser-persistent state',()=>{const source='app Tasks\nmodel Task { title text required }\ncomponent TaskRow { button "Duplicate" on duplicate with task from task button "Remove" on remove with task from task }\npage Home { event duplicate(task Task) appends task to tasks event remove(task Task) removes task from tasks state tasks list<Task> = [] persisted in local storage for each task in tasks show TaskRow }';const result=compile(source);expect(result.diagnostics).toEqual([]);const page=result.ir!.ui!.components.find(component=>component.name==='Home')!;expect(page.state[0]).toMatchObject({name:'tasks',initial:[],persisted:'local',storageKey:expect.stringContaining('bmec-state:Tasks')});expect(page.events).toMatchObject([{name:'duplicate',stateUpdate:{operation:'append',state:'tasks',parameter:'task',type:{kind:'model',name:'Task'},storageKey:page.state[0]!.storageKey}},{name:'remove',stateUpdate:{operation:'remove',state:'tasks',parameter:'task'}}]);expect(page.children).toContainEqual(expect.objectContaining({kind:'list',source:'tasks',item:'task'}));const directory=mkdtempSync(join(tmpdir(),'bmec-ui-state-update-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('data-pipe-state-update=');expect(html).toContain('bmec-state');bundleBrowserArtifact(directory);const bundle=readFileSync(join(directory,'app.js'),'utf8');expect(bundle).toContain('PIPE_UI_APPLY_STATE_UPDATE');expect(bundle).toContain('localStorage');});
 it('projects a product row into a typed cart line before append',()=>{const source='app Shop\nmodel Product { id integer name text price money }\ntype CartLine { productId integer name text unitPrice money quantity integer }\napi /products from Product\ncomponent ProductRow { button "Add" on add with product from product }\npage Store { event add(product Product) appends product as CartLine { productId: product.id, name: product.name, unitPrice: product.price, quantity: 1 } to cart state cart list<CartLine> = [] persisted in local storage state products list<Product> from GET "/products" for each product in products show ProductRow }';const result=compile(source);expect(result.diagnostics).toEqual([]);const update=result.ir!.ui!.components.find(component=>component.name==='Store')!.events[0]!.stateUpdate!;expect(update.type).toMatchObject({kind:'record',name:'CartLine'});expect(update.projection).toMatchObject({type:{kind:'record',name:'CartLine'},fields:{productId:{kind:'field',path:'id'},name:{kind:'field',path:'name'},unitPrice:{kind:'field',path:'price'},quantity:{kind:'literal',value:1}}});const bad=compile(source.replace('quantity: 1','quantity: product.name'));expect(bad.diagnostics.map(item=>item.code)).toContain('PIPE-UI-023');});
 it('preserves source order for page lists and reusable components in the UI IR',()=>{const result=compile('app Shop\nmodel Item { name text }\ncomponent Intro { text "Intro" }\ncomponent Row { show item name }\ncomponent Cart { text "Cart" }\npage Home { state items list<Item> = [] use Intro for each item in items show Row use Cart }');expect(result.diagnostics).toEqual([]);const page=result.ir!.ui!.components.find(component=>component.name==='Home')!;expect(page.children.map(child=>child.kind==='component'?result.ir!.ui!.components.find(component=>component.id===child.componentId)!.name:child.kind)).toEqual(['Intro','list','Cart']);});
 it('compiles typed numeric field updates and rejects nonnumeric row fields',()=>{const source='app Shop\nmodel CartLine { product text required quantity integer required }\ncomponent CartRow { button "More" on more with line from line button "Less" on less with line from line }\npage Cart { event more(line CartLine) increases quantity of line in cart event less(line CartLine) decreases quantity of line in cart state cart list<CartLine> = [] for each line in cart show CartRow }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components.find(component=>component.name==='Cart')!.events).toMatchObject([{name:'more',stateUpdate:{operation:'increment',state:'cart',parameter:'line',field:'quantity'}},{name:'less',stateUpdate:{operation:'decrement',state:'cart',parameter:'line',field:'quantity'}}]);const bad=compile('app Shop\nmodel CartLine { title text required }\ncomponent Row { button "More" on more with line from line }\npage Cart { event more(line CartLine) increases quantity of line in cart state cart list<CartLine> for each line in cart show Row }');expect(bad.diagnostics.map(item=>item.code)).toContain('PIPE-UI-021');});
 it('compiles a typed derived subtotal for money and rejects text-valued aggregate fields',()=>{const result=compile('app Shop\nmodel CartLine { price money quantity integer }\ncomponent Summary { text "Subtotal: $" show total of cart by price times quantity }\npage Cart { state cart list<CartLine> = [] use Summary }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components.find(component=>component.name==='Summary')!.children).toContainEqual({kind:'aggregate',source:'cart',field:'price',multiplier:'quantity',money:true});expect(validateSerializedIR(result.ir).valid).toBe(true);const bad=compile('app Shop\nmodel CartLine { price text quantity integer }\ncomponent Summary { show total of cart by price times quantity }\npage Cart { state cart list<CartLine> use Summary }');expect(bad.diagnostics.map(item=>item.code)).toContain('PIPE-UI-022');});
 it('rejects invalid or mixed browser state updates and persisted remote state',()=>{const wrongType=compile('app Tasks\nmodel Task { title text }\ncomponent Row { button "Add" on add with task from task }\npage Home { event add(task text) appends task to tasks state tasks list<Task> for each task in tasks show Row }');expect(wrongType.diagnostics.map(item=>item.code)).toContain('PIPE-UI-021');const remote=compile('app Tasks\nmodel Task { title text }\npage Home { state tasks list<Task> persisted in local storage from GET "/tasks" }');expect(remote.diagnostics.map(item=>item.code)).toContain('PIPE-UI-020');});
 it('type-checks a page event against an API route and emits a browser action contract',()=>{const source='app Shop\nmodel Order { productId id quantity integer }\napi /orders from Order\ncomponent CartForm form { input productId id label "Product" input quantity integer label "Quantity" button "Add to cart" on add }\npage Store { event add(productId id, quantity integer) sends POST "/orders" use CartForm }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.events).toMatchObject([{name:'add',action:{method:'POST',path:'/orders'}}]);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-action-'));generate(result.ir!,directory);expect(readFileSync(join(directory,'index.html'),'utf8')).toContain('data-pipe-action=');});
 it('requires an explicit idempotency contract and emits it in the public action metadata',()=>{const source='app Shop\ntype CheckoutRequest { quantity integer }\nasync function submit(db capability<database>, body CheckoutRequest, idempotencyKey text) -> task<integer> { return 1 }\nhttp POST /orders headers idempotencyKey requires database -> submit\ncomponent CheckoutForm form { input quantity integer label "Quantity" button "Submit" on submit }\npage Store { event submit(quantity integer) sends POST "/orders" with idempotency key use CheckoutForm }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.events).toMatchObject([{name:'submit',action:{method:'POST',path:'/orders',idempotencyKey:true}}]);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-idempotency-'));generate(result.ir!,directory);expect(readFileSync(join(directory,'index.html'),'utf8')).toContain('&quot;idempotencyKey&quot;:true');});
 it('rejects idempotent actions without a matching required route header',()=>{const source='app Shop\ntype CheckoutRequest { quantity integer }\nasync function submit(body CheckoutRequest) -> integer { return 1 }\nhttp POST /orders -> submit\ncomponent CheckoutForm form { input quantity integer label "Quantity" button "Submit" on submit }\npage Store { event submit(quantity integer) sends POST "/orders" with idempotency key use CheckoutForm }';expect(compile(source).diagnostics.map(error=>error.code)).toContain('PIPE-UI-015');});
 it('rejects UI actions with an unknown route, mismatched request fields, dynamic paths without a matching route, or no matching form',()=>{const missing=compile('app Shop\nmodel AddOrder { quantity integer }\npage Store { event add(quantity integer) sends POST "/missing" }');expect(missing.diagnostics.map(d=>d.code)).toContain('PIPE-UI-011');const mismatch=compile('app Shop\nmodel Order { productId id quantity integer }\napi /orders from Order\npage Store { event add(quantity integer) sends POST "/orders" }');expect(mismatch.diagnostics.map(d=>d.code)).toContain('PIPE-UI-012');const dynamic=compile('app Shop\nmodel Order { quantity integer }\napi /orders from Order\npage Store { event change(quantity integer) sends PUT "/orders/:id" }');expect(dynamic.diagnostics.map(d=>d.code)).toContain('PIPE-UI-011');const noForm=compile('app Shop\nmodel Order { quantity integer }\napi /orders from Order\npage Store { event add(quantity integer) sends POST "/orders" }');expect(noForm.diagnostics.map(d=>d.code)).toContain('PIPE-UI-014');});
 it('accepts typed UI actions for declared routes with dynamic path parameters',()=>{const source='app Shop\nmodel OrderUpdate { quantity integer }\nfunction updateOrder(orderId id, body OrderUpdate) -> integer { return body.quantity }\nhttp PUT /orders/:orderId -> updateOrder\ncomponent EditOrder form { input orderId id input quantity integer button "Save" on save }\npage Editor { event save(orderId id, quantity integer) sends PUT "/orders/:orderId" use EditOrder }';expect(compile(source).diagnostics).toEqual([]);});
 it('rejects declared actions whose route requires unsupplied query inputs',()=>{const result=compile('app Shop\nmodel Order { quantity integer required }\nasync function create(db capability<database>, body Order, warehouse text) -> task<integer> { return wait for add body to Order using db }\nhttp POST /orders requires database -> create\ncomponent OrderForm form { input quantity integer button "Add" on submit }\npage Store { event submit(quantity integer) sends POST "/orders" use OrderForm }');expect(result.diagnostics.map(d=>d.code)).toContain('PIPE-UI-015');});
 it('lowers page and reusable component links to canonical page component IDs',()=>{const result=compile('app Tasks\ncomponent Navigation { link "Home" to Home }\npage Home { link "View tasks" to Tasks use Navigation }\npage Tasks {}');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toContainEqual({kind:'link',label:'View tasks',targetComponentId:'UI-002'});expect(result.ir!.ui!.components.find(component=>component.id==='COMP-001')!.children).toContainEqual({kind:'link',label:'Home',targetComponentId:'UI-001'});const directory=mkdtempSync(join(tmpdir(),'bmec-ui-nav-'));generate(result.ir!,directory);expect(readFileSync(join(directory,'index.html'),'utf8')).toContain('<a href="#pipe-page--tasks">View tasks</a>');});
 it('rejects navigation links to undeclared pages',()=>{const result=compile('app Tasks\npage Home { link "Missing" to Missing }');expect(result.diagnostics).toMatchObject([expect.objectContaining({code:'PIPE-UI-006',received:'Missing'})]);});
 it('lowers typed dynamic page routes and item-bound links',()=>{const source='app Journal\nmodel Post { title text slug text required unique body text }\ncomponent ArticleRow { link "Read" to Article with slug post.slug }\ncomponent ArticleDetail { show post title }\nasync function published(db capability<database>) -> task<list<Post>> { return wait for get posts from Post ordered by title ascending limited to 50 using db }\nhttp GET /published-posts requires database -> published\npage Articles { state posts list<Post> from GET "/published-posts" for each post in posts show ArticleRow }\npage Article at "/articles/:slug" { state posts list<Post> from GET "/published-posts" for each post in posts show ArticleDetail empty "Not found." }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.pages.find(page=>page.name==='Article')?.route).toBe('/articles/:slug');expect(result.ir!.ui!.routes).toContainEqual({path:'/articles/:slug',componentId:'UI-002'});expect(result.ir!.ui!.components.find(component=>component.name==='ArticleRow')?.children).toContainEqual({kind:'link',label:'Read',targetComponentId:'UI-002',parameters:[{name:'slug',path:'post.slug'}]});});
 it('allows a matching typed dynamic GET page-state route',()=>{const source='app Journal\nmodel Post { title text slug text required unique }\nasync function bySlug(db capability<database>, slug text) -> task<list<Post>> { return wait for get posts from Post where slug is slug ordered by title ascending limited to 1 using db }\nhttp GET /posts/:slug requires database -> bySlug\npage Article at "/posts/:slug" { state posts list<Post> from GET "/posts/:slug" for each post in posts show post title }';expect(compile(source).diagnostics).toEqual([]);});
 it('validates integer dynamic page-state parameters with any matching name',()=>{const source='app Store\nmodel Product { name text required }\nasync function byProductId(db capability<database>, productId integer) -> task<list<Product>> { return await get items from Product where id is productId using db }\nhttp GET /products/:productId requires database -> byProductId\npage ProductDetails at "/product/:productId" { state selected list<Product> from GET "/products/:productId" for each product in selected show product name }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(validateSerializedIR(result.ir!).valid).toBe(true);});
 it('checks typed page search and search-aware cursor routes in serialized UI IR',()=>{
  const source='app SearchableJournal\nmodel Post { title text slug text required unique published boolean required }\nasync function initial(db capability<database>) -> task<list<Post>> { return wait for get posts from Post where published is true ordered by slug ascending limited to 50 using db }\nasync function search(db capability<database>, term text) -> task<list<Post>> { return wait for get posts from Post where published is true and title contains term ordered by slug ascending limited to 50 using db }\nasync function next(db capability<database>, term text, after text) -> task<list<Post>> { return wait for get posts from Post where published is true and title contains term and slug is greater than after ordered by slug ascending limited to 50 using db }\nasync function nextBase(db capability<database>, after text) -> task<list<Post>> { return wait for get posts from Post where published is true and slug is greater than after ordered by slug ascending limited to 50 using db }\nhttp GET /posts requires database -> initial\nhttp GET /posts/pages/:after requires database -> nextBase\nhttp GET /posts/search/:term requires database -> search\nhttp GET /posts/search/:term/pages/:after requires database -> next\ncomponent Row { show post title }\npage Articles { state posts list<Post> from GET "/posts" next GET "/posts/pages/:after" cursor by slug search GET "/posts/search/:term" next GET "/posts/search/:term/pages/:after" cursor by slug for each post in posts show Row filter by title }';
  const compiled=compile(source);expect(compiled.diagnostics).toEqual([]);expect(compiled.ir!.ui!.components[0]!.state[0]!.source).toEqual({method:'GET',path:'/posts',next:{method:'GET',path:'/posts/pages/:after',parameter:'after',cursorField:'slug'},search:{method:'GET',path:'/posts/search/:term',parameter:'term',next:{method:'GET',path:'/posts/search/:term/pages/:after',parameter:'after',cursorField:'slug'}}});expect(validateSerializedIR(compiled.ir).valid).toBe(true);
  const tampered=structuredClone(compiled.ir!) as any;tampered.ui.components[0].state[0].source.search.path='/missing/:term';expect(validateSerializedIR(tampered).valid).toBe(false);
  const badCursorSource=source.replace(' next GET "/posts/search/:term/pages/:after" cursor by slug','');expect(compile(badCursorSource).diagnostics).toContainEqual(expect.objectContaining({code:'PIPE-UI-013',kind:'missing_page_search_cursor'}));
 });
 it('binds dynamic page parameters when the server data route has a different prefix',()=>{const source='app Journal\nmodel Post { title text slug text required unique published boolean required }\nasync function bySlug(db capability<database>, slug text) -> task<list<Post>> { return wait for get posts from Post where published is true and slug is slug ordered by title ascending limited to 1 using db }\nhttp GET /published-posts/:slug requires database -> bySlug\npage Article at "/articles/:slug" { state posts list<Post> from GET "/published-posts/:slug" for each post in posts show post title }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('rejects dynamic page links with missing parameters or non-text item fields',()=>{const missing=compile('app X\npage Article at "/articles/:slug" {}\npage Home { link "Read" to Article }');expect(missing.diagnostics).toContainEqual(expect.objectContaining({code:'PIPE-UI-017',kind:'invalid_route_link_parameters'}));const wrong=compile('app X\nmodel Post { slug integer }\ncomponent Row { link "Read" to Article with slug post.slug }\npage Home { state posts list<Post> for each post in posts show Row }\npage Article at "/articles/:slug" { state posts list<Post> for each post in posts show post slug }');expect(wrong.diagnostics).toContainEqual(expect.objectContaining({code:'PIPE-UI-017',kind:'invalid_route_link_binding'}));});
 it('lowers inline page-list field display into existing list binding IR',()=>{const result=compile('app Tasks\nmodel User { name text }\npage Home { state users list<User> for each user in users show user name }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual([{kind:'list',source:'users',item:'user',body:[{kind:'binding',path:'user.name'}]}]);});
 it('preserves a typed page-list empty message and loading/error precedence in generated markup and runtime',()=>{const result=compile('app Tasks\ncomponent TaskRow { text "Task" }\npage Home { state loading boolean state error boolean state tasks list<text> loading "Loading tasks" error "Unable to load tasks" for each task in tasks show TaskRow empty "No tasks yet" }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toContainEqual({kind:'list',source:'tasks',item:'task',body:[{kind:'component',componentId:'COMP-001',props:{}}],empty:'No tasks yet'});expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-list-empty-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('data-pipe-list-empty="No tasks yet"');expect(html).toContain("message&&!UI_STATE[list.dataset.pipeListLoadingState]&&!UI_STATE[list.dataset.pipeListErrorState]");expect(html).toContain("status.setAttribute('role','status')");expect(html).toContain("status.setAttribute('aria-live','polite')");});
 it('generates accessible filter and pagination controls for typed record lists',()=>{const result=compile('app Tasks\nmodel Task { title text }\ncomponent TaskRow { show task title }\npage Home { state tasks list<Task> for each task in tasks show TaskRow filter by title paginate 20 }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children[0]).toMatchObject({kind:'list',filterBy:'title',pageSize:20});const directory=mkdtempSync(join(tmpdir(),'bmec-ui-list-filter-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('<label>Filter by Title <input type="search" data-pipe-list-filter aria-label="Filter by Title"></label>');expect(html).toContain('data-pipe-list-filter-by="title"');expect(html).toContain('data-pipe-list-page-size="20"');expect(html).toContain('<nav aria-label="List pages"><button type="button" data-pipe-list-prev aria-label="Previous page">Previous</button><span data-pipe-list-range></span><button type="button" data-pipe-list-next aria-label="Next page">Next</button></nav>');expect(html).toContain("search?.addEventListener('input',()=>{pageIndex=0;draw()})");});
 it('keeps server-search results intact and uses the declared accessible filter label',()=>{const source=readFileSync('examples/community-issues/main.bmec','utf8'),result=compile(source);expect(result.diagnostics).toEqual([]);expect(validateSerializedIR(result.ir).valid).toBe(true);const page=result.ir!.ui!.components.find(component=>component.name==='Issues')!,list=page.children.find(child=>child.kind==='list')!;expect(list).toMatchObject({kind:'list',filterLabel:'Search issues by title or description',remoteSearch:true});const detail=result.ir!.ui!.components.find(component=>component.name==='IssueDetail')!;expect(result.ir!.ui!.routes).toContainEqual({path:'/issues/:id',componentId:detail.id});expect(detail.state[0]!.source?.path).toBe('/issues/:id');const row=result.ir!.ui!.components.find(component=>component.name==='IssueRow')!;expect(row.children).toContainEqual(expect.objectContaining({kind:'link',targetComponentId:detail.id,parameters:[{name:'id',path:'issue.id'}]}));const directory=mkdtempSync(join(tmpdir(),'bmec-ui-server-search-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('<label>Search issues by title or description <input type="search" data-pipe-list-filter aria-label="Search issues by title or description"></label>');expect(html).toContain('data-pipe-remote-search="true"');expect(html).toContain("list.dataset.pipeRemoteSearch==='true'?values:");});
 it('rejects unknown or non-text page-list filter fields',()=>{expect(compile('app Tasks\nmodel Task { title text }\ncomponent Row { text "row" }\npage Home { state tasks list<Task> list tasks item Row filter by missing }').diagnostics.map(d=>d.code)).toContain('PIPE-UI-009');expect(compile('app Tasks\nmodel Task { done boolean }\ncomponent Row { text "row" }\npage Home { state tasks list<Task> list tasks item Row filter by done }').diagnostics.map(d=>d.code)).toContain('PIPE-UI-009');});
 it('preserves bounded page sizes in list IR and rejects invalid sizes',()=>{const result=compile('app Tasks\ncomponent Row { text "row" }\npage Home { state tasks list<text> list tasks item Row paginate 20 }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children[0]).toMatchObject({kind:'list',pageSize:20});for(const size of ['0','101','1.5'])expect(compile(`app Tasks\ncomponent Row { text "row" }\npage Home { state tasks list<text> list tasks item Row paginate ${size} }`).diagnostics.map(d=>d.code)).toContain('PIPE-UI-010');});
 it('rejects a bound field that is not present on the page-list item type',()=>{const result=compile('app Tasks\nmodel User { name text }\ncomponent Row { show task missing }\npage Home { state tasks list<User> for each task in tasks show Row }');expect(result.diagnostics.map(d=>d.code)).toContain('PIPE-UI-007');});
 it('rejects a binding receiver that is not the page-list item',()=>{const result=compile('app Tasks\nmodel User { name text }\ncomponent Row { show user name }\npage Home { state tasks list<User> for each task in tasks show Row }');expect(result.diagnostics.map(d=>d.code)).toContain('PIPE-UI-006');});
});

describe('source UI state and event semantics',()=>{
 it('humanizes reusable component input labels in generated markup',()=>{const result=compile('app Dashboard\ncomponent TaskForm { input dueDate datetime }\npage Home { use TaskForm }');expect(result.diagnostics).toEqual([]);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-labels-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('<label>Due Date ');expect(html).toContain('aria-label="Due Date"');});
 it('preserves typed input placeholders through UI IR and generated markup',()=>{const result=compile('app Dashboard\ncomponent TaskForm { input dueDate datetime label "Due date" placeholder "YYYY-MM-DD" help "Use ISO calendar format" readonly }\npage Home { input search text label "Search" placeholder "Find a task" help "Search by title or ID" disabled use TaskForm }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children[0]).toMatchObject({kind:'input',name:'search',label:'Search',placeholder:'Find a task',help:'Search by title or ID',disabled:true});expect(result.ir!.ui!.components[1]!.children[0]).toMatchObject({kind:'input',name:'dueDate',label:'Due date',placeholder:'YYYY-MM-DD',help:'Use ISO calendar format',readOnly:true});const directory=mkdtempSync(join(tmpdir(),'bmec-ui-placeholder-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('aria-label="Search"');expect(html).toContain('placeholder="Find a task"');expect(html).toContain('Search by title or ID');expect(html).toContain('disabled aria-disabled="true"');expect(html).toContain('aria-describedby="pipe-UI-001-search-help pipe-UI-001-search-error"');expect(html).toContain('aria-label="Due Date"');expect(html).toContain('placeholder="YYYY-MM-DD"');expect(html).toContain('Use ISO calendar format');expect(html).toContain('readonly aria-readonly="true"');expect(html).toContain('aria-describedby="pipe-COMP-001-dueDate-help pipe-COMP-001-dueDate-error"');});
 it('projects semantic email and password controls without changing typed values',()=>{const result=compile('app Auth\npage Login { input email text validate email input secret text password }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual(expect.arrayContaining([expect.objectContaining({kind:'input',name:'email',validation:'email'}),expect.objectContaining({kind:'input',name:'secret',password:true})]));const directory=mkdtempSync(join(tmpdir(),'bmec-ui-input-modes-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('name="email"');expect(html).toContain('type="email"');expect(html).toContain('name="secret"');expect(html).toContain('type="password"');});
 it('marks required generated fields without exposing implementation names',()=>{const result=compile('app Dashboard\nmodel Task { scheduledDate date required }\npage Home { crud Task }');expect(result.diagnostics).toEqual([]);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-required-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('<label>Scheduled Date<span class="pipe-required-mark" aria-hidden="true"> *</span>');expect(html).toContain('name="scheduledDate"');expect(html).toContain('required aria-required="true"');});
 it('excludes optional server-managed fields from generated CRUD controls and columns',()=>{const result=compile('app Dashboard\nmodel Task { title text required ownerAuthId text? internalFlag boolean? }\npage Home { crud Task excluding ownerAuthId, internalFlag }');expect(result.diagnostics).toEqual([]);expect(result.ir!.pages[0]).toMatchObject({crud:['Task'],crudExcludedFields:[{model:'Task',fields:['ownerAuthId','internalFlag']}]});expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-excluded-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('Title');expect(html).not.toContain('Owner Auth Id');expect(html).not.toContain('Internal Flag');expect(html).toContain('data-pipe-crud-excluded-fields="[&quot;ownerAuthId&quot;,&quot;internalFlag&quot;]"');});
 it('rejects invalid generated CRUD field exclusions',()=>{const unknown=compile('app Dashboard\nmodel Task { title text }\npage Home { crud Task excluding missing }');expect(unknown.diagnostics.map(item=>item.code)).toContain('PIPE-UI-014');const required=compile('app Dashboard\nmodel Task { title text required }\npage Home { crud Task excluding title }');expect(required.diagnostics.map(item=>item.code)).toContain('PIPE-UI-015');const duplicate=compile('app Dashboard\nmodel Task { owner text? }\npage Home { crud Task excluding owner, owner }');expect(duplicate.diagnostics.map(item=>item.code)).toContain('PIPE-UI-016');});
 it('preserves readable input labels through canonical UI IR',()=>{const result=compile('app Dashboard\ncomponent Login { input id text label "User ID" validate nonempty }\npage Home { use Login }');expect(result.diagnostics).toEqual([]);const login=result.ir!.ui!.components.find(component=>component.name==='Login')!;expect(login.children).toEqual([{kind:'input',name:'id',label:'User ID',type:{kind:'primitive',name:'text'},validation:'nonempty'}]);expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('lowers typed page state, events, and inputs into canonical UI IR',()=>{const source='app Dashboard\npage Home { state loading boolean = false state query text event refresh() event select(id id) input search text on select crud Item }\nmodel Item { name text }';const ast=parse(source);const page=ast.declarations.find(x=>x.kind==='PageDeclaration')!;expect(page.kind==='PageDeclaration'&&page.statements.map(x=>x.kind)).toEqual(['PageStateDeclaration','PageStateDeclaration','PageEventDeclaration','PageEventDeclaration','PageInputDeclaration','CrudStatement']);const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui).toMatchObject({components:[{id:'UI-001',state:[{name:'loading',type:{kind:'primitive',name:'boolean'},initial:false},{name:'query',type:{kind:'primitive',name:'text'}}],events:[{name:'refresh',parameters:{}},{name:'select',parameters:{id:{kind:'primitive',name:'id'}}}],children:[{kind:'input',name:'search',event:'select'}]}],routes:[{path:'/home',componentId:'UI-001'}]});expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('binds typed list page state to a compatible public GET route',()=>{const source='app Dashboard\nmodel Task { name text }\nasync function listTasks(db capability<database>) -> task<list<Task>> { return wait for get records from Task using db }\nhttp GET /tasks requires database -> listTasks\ncomponent Row { text "Task" }\npage Home { state tasks list<Task> from GET "/tasks" for each task in tasks show Row }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.state).toEqual([{name:'tasks',type:{kind:'list',element:{kind:'model',name:'Task',symbol:expect.any(String)}},source:{method:'GET',path:'/tasks'}}]);expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('allows page state to use the authenticated request Principal without making it a URL parameter',()=>{const source='app Dashboard\ntype Principal { id text }\nmodel Task { name text required ownerAuthId text required }\nasync function listTasks(principal Principal, db capability<database>) -> task<list<Task>> { let ownerAuthId = principal.id return wait for get records from Task where ownerAuthId is ownerAuthId using db }\nhttp GET /tasks requires authenticated, database -> listTasks\ncomponent Row { text "Task" }\npage Home { state tasks list<Task> from GET "/tasks" for each task in tasks show Row }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.http!.routes[0]).toMatchObject({method:'GET',path:'/tasks',policyId:'authenticated',pathParams:[],query:[]});expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('rejects a serialized UI source whose route response type was changed',()=>{const result=compile('app Dashboard\nmodel Task { name text }\napi /tasks from Task\ncomponent Row { text "Task" }\npage Home { state tasks list<Task> from GET "/tasks" list tasks item Row }');expect(result.diagnostics).toEqual([]);const tampered=structuredClone(result.ir!) as any;tampered.http.routes[0].responseBody={kind:'primitive',name:'text'};expect(validateSerializedIR(tampered).errors).toContain('IR ui: page state source for "tasks" must match a static GET or its page\'s typed dynamic GET response type');});
 it('rejects a page-state source whose GET response type does not match',()=>{const source='app Dashboard\nmodel Task { name text }\nasync function listTasks(db capability<database>) -> task<list<Task>> { return wait for get records from Task using db }\nhttp GET /tasks requires database -> listTasks\npage Home { state tasks list<text> from GET "/tasks" }';expect(compile(source).diagnostics.map(d=>d.code)).toContain('PIPE-UI-011');});
 it('diagnoses duplicate page members and unknown state types',()=>{const result=compile('app Dashboard\npage Home { state loading boolean state loading Unknown event refresh() event refresh(id id) }');expect(result.diagnostics.map(d=>d.code)).toEqual(expect.arrayContaining(['PIPE-UI-001','PIPE-TYP-001']));});
 it('parses and lowers a source component with typed children',()=>{const result=compile('app Dashboard\ncomponent TaskForm { text "Create task" input title text validate nonempty }\npage Home { crud Item }\nmodel Item { name text }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components).toEqual(expect.arrayContaining([expect.objectContaining({id:'COMP-001',name:'TaskForm',children:[{kind:'text',value:'Create task'},{kind:'input',name:'title',type:{kind:'primitive',name:'text'},validation:'nonempty'}]})]));expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('composes a declared component inside another component',()=>{const result=compile('app Dashboard\ncomponent Badge { text "Status" }\ncomponent Row { use Badge }\npage Home { use Row }');expect(result.diagnostics).toEqual([]);const row=result.ir!.ui!.components.find(component=>component.name==='Row')!;expect(row.children).toEqual([{kind:'component',componentId:'COMP-001',props:{}}]);expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('mounts a declared component from a routed page',()=>{const result=compile('app Dashboard\ncomponent TaskForm { text "Create task" }\npage Home { use TaskForm crud Item }\nmodel Item { name text }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual([{kind:'component',componentId:'COMP-001',props:{}}]);});
 it('diagnoses unknown source input validation rules',()=>{const result=compile('app Dashboard\ncomponent TaskForm { input title text validate trim }\npage Home { input search text validate trim }');expect(result.diagnostics.map(d=>d.code)).toEqual(['PIPE-UI-004','PIPE-UI-004']);});
 it('lowers page loading and error feedback into semantic accessible UI nodes',()=>{const result=compile('app Dashboard\npage Home { loading "Loading tasks" error "Unable to load tasks" }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual([{kind:'feedback',state:'loading',value:'Loading tasks'},{kind:'feedback',state:'error',value:'Unable to load tasks'}]);expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-feedback-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('<p data-pipe-condition="loading" role="status" aria-live="polite" hidden>Loading tasks</p>');expect(html).toContain('<p data-pipe-condition="error" role="alert" aria-live="assertive" hidden>Unable to load tasks</p>');});
 it('lowers typed modal dialogs with accessible native dialog markup',()=>{const result=compile('app Dashboard\npage Home { dialog "Open details" title "Project details" message "This project is ready." }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual([{kind:'dialog',dialogId:'DIALOG-001',label:'Open details',title:'Project details',message:'This project is ready.'}]);expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-dialog-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('aria-haspopup="dialog" aria-controls="DIALOG-001"');expect(html).toContain('<dialog id="DIALOG-001" aria-labelledby="DIALOG-001-title"><form method="dialog"><h2 id="DIALOG-001-title">Project details</h2><p>This project is ready.</p><button type="submit">Close</button>');});
 it('lowers accessible dialogs inside reusable components with unique IDs',()=>{const result=compile('app Shop\ncomponent Product { text "Cup" dialog "View details" title "Cup" message "Ceramic cup." }\ncomponent Featured { dialog "Read more" title "Story" message "A small batch." }\npage Home { use Product use Featured dialog "Help" title "Help" message "Store help." }');expect(result.diagnostics).toEqual([]);const dialogs=result.ir!.ui!.components.flatMap(component=>component.children.filter(child=>child.kind==='dialog'));expect(dialogs.map(dialog=>dialog.dialogId)).toEqual(['DIALOG-001','DIALOG-002','DIALOG-003']);expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-component-dialog-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('aria-haspopup="dialog" aria-controls="DIALOG-002"');expect(html).toContain('<dialog id="DIALOG-002"');expect(html).toContain('<dialog id="DIALOG-003"');});
 it('lowers a source list declaration to a typed component list node',()=>{const result=compile('app Dashboard\ncomponent Row { text "row" }\npage Home { state items list<text> list items item Row }');expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual([{kind:'list',source:'items',item:'item',body:[{kind:'component',componentId:'COMP-001',props:{}}]}]);});
 it('checks a typed GET cursor continuation and rejects malformed serialized cursor contracts',()=>{const source='app Explorer\nmodel Row { name text required unique }\nasync function first(db capability<database>) -> task<list<Row>> { return wait for get rows from Row ordered by name ascending limited to 50 using db }\nasync function after(db capability<database>, after text) -> task<list<Row>> { return wait for get rows from Row where name is greater than after ordered by name ascending limited to 50 using db }\nhttp GET /rows requires database -> first\nhttp GET /rows/:after requires database -> after\npage Home { state rows list<Row> from GET "/rows" next GET "/rows/:after" cursor by name for each row in rows show row name }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.state[0]!.source?.next).toEqual({method:'GET',path:'/rows/:after',parameter:'after',cursorField:'name'});expect(validateSerializedIR(result.ir).valid).toBe(true);const malformed=structuredClone(result.ir!);malformed.ui!.components[0]!.state[0]!.source!.next!.path='/rows/:missing';expect(validateSerializedIR(malformed).valid).toBe(false);});
 it('preserves scoped route parameters in a typed cursor continuation',()=>{const source='app Repositories\nmodel Issue { slug text title text }\nasync function first(db capability<database>, slug text) -> task<list<Issue>> { return wait for get issues from Issue where slug is slug ordered by id ascending limited to 50 using db }\nasync function after(db capability<database>, slug text, after integer) -> task<list<Issue>> { return wait for get issues from Issue where slug is slug and id is greater than after ordered by id ascending limited to 50 using db }\nhttp GET /repositories/:slug/issues requires database -> first\nhttp GET /repositories/:slug/issues/pages/:after requires database -> after\ncomponent IssueRow { show issue title }\npage Issues at "/repositories/:slug/issues" { state issues list<Issue> from GET "/repositories/:slug/issues" next GET "/repositories/:slug/issues/pages/:after" cursor by id for each issue in issues show IssueRow }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components.find(component=>component.name==='Issues')!.state[0]!.source!.next).toEqual({method:'GET',path:'/repositories/:slug/issues/pages/:after',parameter:'after',cursorField:'id'});expect(validateSerializedIR(result.ir).valid).toBe(true);});
 it('preserves page scope in a typed search and search cursor continuation',()=>{const source='app Repositories\nmodel Issue { repositorySlug text title text description text }\nasync function first(db capability<database>, slug text) -> task<list<Issue>> { return wait for get issues from Issue where repositorySlug is slug ordered by id ascending limited to 50 using db }\nasync function search(db capability<database>, slug text, term text) -> task<list<Issue>> { return wait for get issues from Issue where repositorySlug is slug and (title contains term or description contains term) ordered by id ascending limited to 50 using db }\nasync function after(db capability<database>, slug text, term text, after integer) -> task<list<Issue>> { return wait for get issues from Issue where repositorySlug is slug and (title contains term or description contains term) and id is greater than after ordered by id ascending limited to 50 using db }\nhttp GET /repositories/:slug/issues requires database -> first\nhttp GET /repositories/:slug/issues/search/:term requires database -> search\nhttp GET /repositories/:slug/issues/search/:term/pages/:after requires database -> after\ncomponent IssueRow { show issue title }\npage Issues at "/repositories/:slug/issues" { state issues list<Issue> from GET "/repositories/:slug/issues" search GET "/repositories/:slug/issues/search/:term" next GET "/repositories/:slug/issues/search/:term/pages/:after" cursor by id for each issue in issues show IssueRow filter by title }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components.find(component=>component.name==='Issues')!.state[0]!.source!.search).toEqual({method:'GET',path:'/repositories/:slug/issues/search/:term',parameter:'term',next:{method:'GET',path:'/repositories/:slug/issues/search/:term/pages/:after',parameter:'after',cursorField:'id'}});expect(validateSerializedIR(result.ir).valid).toBe(true);const malformed=structuredClone(result.ir!);malformed.ui!.components.find(component=>component.name==='Issues')!.state[0]!.source!.search!.path='/repositories/issues/search/:term';expect(validateSerializedIR(malformed).valid).toBe(false);});
 it('keeps the generated cursor button inside the list region used by its runtime',()=>{const result=compile('app Explorer\nmodel Row { name text required unique }\nasync function first(db capability<database>) -> task<list<Row>> { return wait for get rows from Row ordered by name ascending limited to 50 using db }\nasync function after(db capability<database>, after text) -> task<list<Row>> { return wait for get rows from Row where name is greater than after ordered by name ascending limited to 50 using db }\nhttp GET /rows requires database -> first\nhttp GET /rows/:after requires database -> after\ncomponent RowView { show row name }\npage Home { state rows list<Row> from GET "/rows" next GET "/rows/:after" cursor by name for each row in rows show RowView }');expect(result.diagnostics).toEqual([]);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-cursor-control-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toMatch(/<div data-pipe-list-region>[\s\S]*?<button[^>]*data-pipe-cursor-state="rows"/);expect(html).toContain('data-pipe-cursor-status="rows"');});
 it('accepts a generated integer model ID cursor and connects it to CRUD paging',()=>{const source='app Tasks\nmodel Task { title text required }\nasync function first(db capability<database>) -> task<list<Task>> { return wait for get tasks from Task ordered by id ascending limited to 50 using db }\nasync function after(db capability<database>, after integer) -> task<list<Task>> { return wait for get tasks from Task where id is greater than after ordered by id ascending limited to 50 using db }\napi /tasks from Task\nhttp GET /tasks requires database -> first\nhttp GET /tasks/pages/:after requires database -> after\npage Dashboard { state tasks list<Task> from GET "/tasks" next GET "/tasks/pages/:after" cursor by id crud Task }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(validateSerializedIR(result.ir).valid).toBe(true);const directory=mkdtempSync(join(tmpdir(),'bmec-ui-crud-cursor-'));generate(result.ir!,directory);const html=readFileSync(join(directory,'index.html'),'utf8');expect(html).toContain('data-pipe-cursor-field="id"');expect(html).toContain('data-pipe-crud-cursor-next');expect(html).toContain('data-pipe-cursor-status="tasks"');expect(html).toContain('data-edit=');expect(html).toContain('data-delete=');});
 it('diagnoses an unknown list component',()=>{const result=compile('app Dashboard\npage Home { list tasks item Missing }');expect(result.diagnostics.map(d=>d.code)).toContain('PIPE-UI-003');});
 it('diagnoses a list source that is missing or not a list state',()=>{const result=compile('app Dashboard\ncomponent Row { text "row" }\npage Home { state tasks text list tasks item Row }');expect(result.diagnostics.map(d=>d.code)).toContain('PIPE-UI-005');});
 it('lowers controlled-English for-each page lists into the existing list IR',()=>{const source='app Dashboard\ncomponent Row { text "row" }\npage Home { state tasks list<text> for each task in tasks show Row }';const result=compile(source);expect(result.diagnostics).toEqual([]);expect(result.ir!.ui!.components[0]!.children).toEqual([{kind:'list',source:'tasks',item:'task',body:[{kind:'component',componentId:'COMP-001',props:{}}]}]);});
 it('rejects unknown controlled-English page-list components',()=>{expect(compile('app Dashboard\npage Home { for each task in tasks show Missing }').diagnostics.map(d=>d.kind)).toContain('unknown_component');});
});
